-- LH-1.0.0-draft.1. Additive, legacy enrollment defaults false.
-- Generated by CLI 2.111.0; advanced after the existing 20261031000000 migration.
-- Rehearse only in an explicitly disposable project. No research content is seeded.
create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create collation public.local_heroes_vi (provider = icu, locale = 'vi', deterministic = true);

create function public.local_hero_fold(p_value text) returns text
language sql immutable security invoker set search_path = '' as $$
  select lower(translate(regexp_replace(normalize(btrim(regexp_replace(regexp_replace(coalesce(p_value,''), U&'[\0009-\000d\0020\0085\00a0\1680\2000-\200a\2028\2029\202f\205f\3000]+',' ','g'),U&'[\0001-\0008\000e-\001f\007f-\009f\200b\feff]','','g')), NFD), U&'[\0300-\036f]', '', 'g'), 'đĐ', 'dD') collate public.local_heroes_vi)
$$;
revoke all on function public.local_hero_fold(text) from public;
grant execute on function public.local_hero_fold(text) to anon, authenticated;

create function public.local_hero_aliases_valid(p_values text[]) returns boolean
language sql immutable security invoker set search_path = '' as $$
  select p_values is not null and cardinality(p_values) <= 20
    and not exists(select 1 from unnest(p_values) v where v is null or length(btrim(v))=0 or length(v)>160 or v <> normalize(v,NFC))
    and cardinality(p_values)=(select count(distinct v) from unnest(p_values) v)
$$;
revoke all on function public.local_hero_aliases_valid(text[]) from public, anon;
grant execute on function public.local_hero_aliases_valid(text[]) to authenticated;

alter table public.historical_figures
  add column is_local_hero boolean not null default false,
  add column contribution_summary text,
  add column contribution_start_year integer,
  add column contribution_end_year integer,
  add column catalog_aliases text[] not null default '{}',
  add column local_hero_revision bigint not null default 0,
  add column local_hero_search_text text not null default '',
  add constraint historical_figures_contribution_summary_check check(contribution_summary is null or length(btrim(contribution_summary)) between 1 and 600),
  add constraint historical_figures_contribution_years_check check(
    (contribution_start_year is null and contribution_end_year is null) or
    (contribution_start_year is not null and contribution_end_year is not null and contribution_start_year between 1 and 2200 and contribution_end_year between contribution_start_year and 2200)),
  add constraint historical_figures_catalog_aliases_check check(public.local_hero_aliases_valid(catalog_aliases)),
  add constraint historical_figures_local_hero_revision_check check(local_hero_revision>=0);
create index historical_figures_local_hero_order_idx on public.historical_figures(name collate public.local_heroes_vi, slug collate "C") where is_local_hero and workflow_status='published';

create table public.history_localities (
  code text primary key, slug text not null unique, official_name text not null,
  reference_framework text not null default 'VN-34-2025', source_url text not null,
  source_locator text not null, source_accessed_at date not null,
  constraint history_localities_framework_check check(reference_framework='VN-34-2025')
);
-- Exact tuple CHECK and seed are appended below from the frozen approved registry.

create table public.figure_sources (
  figure_id uuid not null references public.historical_figures(id) on delete cascade,
  claim_key text not null, source_id uuid not null references public.sources(id) on delete restrict,
  claim_text text not null, locator text not null, scope_note text not null,
  certainty text not null, uncertainty_note text,
  primary key(figure_id,claim_key,source_id),
  constraint figure_sources_claim_key_check check(length(claim_key)<=160 and claim_key ~ '^[a-z][a-z0-9_-]*(:[a-z0-9_-]+)*$'),
  constraint figure_sources_certainty_check check(certainty in ('verified','approximate','disputed','editorial')),
  constraint figure_sources_evidence_check check(length(btrim(claim_text))>0 and length(btrim(locator))>0 and length(btrim(scope_note))>0 and (certainty not in ('approximate','disputed') or coalesce(length(btrim(uncertainty_note)),0)>0))
);
create index figure_sources_source_idx on public.figure_sources(source_id,figure_id);

create table public.figure_localities (
  id uuid primary key default gen_random_uuid(),
  figure_id uuid not null references public.historical_figures(id) on delete cascade,
  locality_code text not null references public.history_localities(code) on delete restrict,
  relationship_kind text not null, historical_place_label text not null, explanation text not null,
  claim_key text not null, primary_source_id uuid not null, certainty text not null, uncertainty_note text,
  constraint figure_localities_identity_key unique(figure_id,locality_code,relationship_kind),
  constraint figure_localities_claim_fkey foreign key(figure_id,claim_key,primary_source_id) references public.figure_sources(figure_id,claim_key,source_id) on delete restrict,
  constraint figure_localities_kind_check check(relationship_kind in ('birthplace','home_origin','activity','commemoration')),
  constraint figure_localities_certainty_check check(certainty in ('verified','approximate','disputed','editorial')),
  constraint figure_localities_text_check check(length(btrim(historical_place_label))>0 and length(btrim(explanation))>0 and (certainty not in ('approximate','disputed') or coalesce(length(btrim(uncertainty_note)),0)>0)),
  constraint figure_localities_claim_key_check check(claim_key='locality:'||locality_code||':'||relationship_kind)
);
create index figure_localities_locality_idx on public.figure_localities(locality_code,figure_id);
create index figure_localities_source_idx on public.figure_localities(primary_source_id);

create table public.figure_stories (
  id uuid primary key default gen_random_uuid(), figure_id uuid not null references public.historical_figures(id) on delete cascade,
  slug text not null, title text not null, summary text not null, body text not null,
  sort_order integer not null default 0, is_primary boolean not null default false,
  workflow_status public.content_workflow_status not null default 'draft', review_note text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint figure_stories_figure_slug_key unique(figure_id,slug),
  constraint figure_stories_id_figure_key unique(id,figure_id),
  constraint figure_stories_content_check check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(title) between 1 and 200 and length(summary)<=600 and length(body)<=20000 and sort_order>=0),
  constraint figure_stories_public_note_check check(workflow_status<>'published' or review_note is null)
);
create unique index figure_stories_one_primary_idx on public.figure_stories(figure_id) where is_primary;
create index figure_stories_public_order_idx on public.figure_stories(figure_id,workflow_status,sort_order,id);

create table public.figure_story_sources (
  story_id uuid not null references public.figure_stories(id) on delete cascade,
  claim_key text not null, source_id uuid not null references public.sources(id) on delete restrict,
  claim_text text not null, locator text not null, scope_note text not null, certainty text not null, uncertainty_note text,
  primary key(story_id,claim_key,source_id),
  constraint figure_story_sources_claim_key_check check(length(claim_key)<=160 and claim_key ~ '^[a-z][a-z0-9_-]*(:[a-z0-9_-]+)*$'),
  constraint figure_story_sources_certainty_check check(certainty in ('verified','approximate','disputed','editorial')),
  constraint figure_story_sources_evidence_check check(length(btrim(claim_text))>0 and length(btrim(locator))>0 and length(btrim(scope_note))>0 and (certainty not in ('approximate','disputed') or coalesce(length(btrim(uncertainty_note)),0)>0))
);
create index figure_story_sources_source_idx on public.figure_story_sources(source_id,story_id);

alter table public.media_assets add constraint media_assets_id_figure_key unique(id,figure_id);
create table public.figure_media_evidence (
  media_id uuid primary key, figure_id uuid not null references public.historical_figures(id) on delete cascade,
  depiction_kind text not null, decision text not null default 'held', identity_source_id uuid not null references public.sources(id) on delete restrict,
  identity_locator text not null, identity_certainty text not null, usage_basis text not null,
  usage_source_id uuid references public.sources(id) on delete restrict, usage_locator text, usage_note text, checked_at timestamptz,
  constraint figure_media_evidence_owner_fkey foreign key(media_id,figure_id) references public.media_assets(id,figure_id) on delete cascade,
  constraint figure_media_evidence_depiction_check check(depiction_kind in ('portrait','historical_context')),
  constraint figure_media_evidence_decision_check check(decision in ('accepted','held')),
  constraint figure_media_evidence_certainty_check check(identity_certainty in ('verified','approximate','disputed','editorial')),
  constraint figure_media_evidence_usage_check check(usage_basis in ('open_license','public_domain','permission','coursework_reference','unknown')),
  constraint figure_media_evidence_acceptance_check check(decision<>'accepted' or (
    identity_certainty='verified' and length(btrim(identity_locator))>0 and checked_at is not null and usage_basis<>'unknown'
    and case when usage_basis='coursework_reference' then coalesce(length(btrim(usage_note)),0)>0
      else usage_source_id is not null and coalesce(length(btrim(usage_locator)),0)>0 end))
);
create index figure_media_evidence_figure_idx on public.figure_media_evidence(figure_id,decision);
create index figure_media_evidence_identity_source_idx on public.figure_media_evidence(identity_source_id);
create index figure_media_evidence_usage_source_idx on public.figure_media_evidence(usage_source_id);

