-- Acyclic visibility: parent -> children -> sources. Readiness is a commit invariant.
do $$
declare t text; prefix text; predicate text;
begin
  foreach t in array array['history_localities','figure_sources','figure_localities','figure_stories','figure_story_sources','figure_media_evidence'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public, anon, authenticated',t);
    execute format('grant select on public.%I to anon, authenticated',t);
    if t='history_localities' then
      execute 'create policy lh_localities_read on public.history_localities for select to anon, authenticated using(true)';
      continue;
    end if;
    prefix := case t when 'figure_sources' then 'lh_figure_sources' when 'figure_localities' then 'lh_localities' when 'figure_stories' then 'lh_stories' when 'figure_story_sources' then 'lh_story_sources' else 'lh_media' end;
    predicate := case when t='figure_story_sources' then
      'exists(select 1 from public.figure_stories s join public.historical_figures f on f.id=s.figure_id where s.id=story_id and s.workflow_status=''published'' and f.is_local_hero and f.workflow_status=''published'')'
    else format('exists(select 1 from public.historical_figures f where f.id=%I.figure_id and f.is_local_hero and f.workflow_status=''published'')',t) end;
    if t='figure_stories' then predicate := predicate || ' and workflow_status=''published'''; end if;
    if t='figure_media_evidence' then predicate := predicate || ' and decision=''accepted'''; end if;
    if t='figure_localities' then predicate := predicate || ' and certainty in (''verified'',''approximate'',''disputed'')'; end if;
    execute format('create policy %I on public.%I for select to anon, authenticated using(%s)',prefix||'_public',t,predicate);
    execute format('create policy %I on public.%I for select to authenticated using(public.current_staff_role() is not null)',prefix||'_staff',t);
    execute format('grant insert, update, delete on public.%I to authenticated',t);
    predicate := case when t='figure_story_sources' then
      'exists(select 1 from public.figure_stories s join public.historical_figures f on f.id=s.figure_id where s.id=story_id and f.is_local_hero and f.workflow_status in (''draft'',''needs_revision'') and s.workflow_status in (''draft'',''needs_revision''))'
    else format('exists(select 1 from public.historical_figures f where f.id=%I.figure_id and f.is_local_hero and f.workflow_status in (''draft'',''needs_revision''))',t) end;
    if t='figure_stories' then
      execute format('create policy lh_stories_editable on public.figure_stories for all to authenticated using(public.current_staff_role() in (''editor'',''system_admin'') and %s and workflow_status in (''draft'',''needs_revision'')) with check(public.current_staff_role() in (''editor'',''system_admin'') and %s and workflow_status in (''draft'',''needs_revision'',''pending_review''))',predicate,predicate);
      execute 'create policy lh_stories_review on public.figure_stories for update to authenticated using(public.current_staff_role() in (''reviewer'',''system_admin'')) with check(public.current_staff_role() in (''reviewer'',''system_admin''))';
    else
      execute format('create policy %I on public.%I for all to authenticated using(public.current_staff_role() in (''editor'',''system_admin'') and %s) with check(public.current_staff_role() in (''editor'',''system_admin'') and %s)',prefix||'_editable',t,predicate,predicate);
    end if;
  end loop;
end $$;

drop policy public_read_published on public.media_assets;
create policy public_read_published on public.media_assets for select to anon, authenticated using(
  public.media_owner_status(event_id,figure_id,location_id)='published' and (
    figure_id is null or exists(select 1 from public.historical_figures f where f.id=figure_id and (
      not f.is_local_hero or exists(select 1 from public.figure_media_evidence me where me.media_id=media_assets.id and me.figure_id=f.id and me.decision='accepted')
    ))
  )
);
drop policy public_read_published on public.sources;
create policy public_read_published on public.sources for select to anon, authenticated using(
  exists(select 1 from public.event_sources es join public.historical_events e on e.id=es.event_id where es.source_id=sources.id and e.workflow_status='published')
  or exists(select 1 from public.figure_sources fs join public.historical_figures f on f.id=fs.figure_id where fs.source_id=sources.id and f.is_local_hero and f.workflow_status='published')
  or exists(select 1 from public.figure_story_sources ss join public.figure_stories s on s.id=ss.story_id join public.historical_figures f on f.id=s.figure_id where ss.source_id=sources.id and s.workflow_status='published' and f.is_local_hero and f.workflow_status='published')
  or exists(select 1 from public.figure_media_evidence me join public.historical_figures f on f.id=me.figure_id where (me.identity_source_id=sources.id or me.usage_source_id=sources.id) and me.decision='accepted' and f.is_local_hero and f.workflow_status='published')
  or exists(select 1 from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id join public.historical_figures f on f.id=me.figure_id where ma.source_id=sources.id and me.decision='accepted' and f.is_local_hero and f.workflow_status='published')
);

-- Internal complete-owner lookup. Never exposed or executable by API roles.
create function private.local_hero_owners(p_table text, p_row jsonb) returns setof uuid
language plpgsql stable security definer set search_path='' as $$
begin
  if p_table='historical_figures' then return query select (p_row->>'id')::uuid;
  elsif p_table='figure_story_sources' then return query select s.figure_id from public.figure_stories s where s.id=(p_row->>'story_id')::uuid;
  elsif p_table='sources' then
    return query select fs.figure_id from public.figure_sources fs where fs.source_id=(p_row->>'id')::uuid
    union select s.figure_id from public.figure_story_sources ss join public.figure_stories s on s.id=ss.story_id where ss.source_id=(p_row->>'id')::uuid
    union select me.figure_id from public.figure_media_evidence me where me.identity_source_id=(p_row->>'id')::uuid or me.usage_source_id=(p_row->>'id')::uuid
    union select ma.figure_id from public.media_assets ma where ma.source_id=(p_row->>'id')::uuid and ma.figure_id is not null
    union select fl.figure_id from public.figure_localities fl where fl.primary_source_id=(p_row->>'id')::uuid;
  else return query select (p_row->>'figure_id')::uuid where p_row->>'figure_id' is not null;
  end if;
end $$;
revoke all on function private.local_hero_owners(text,jsonb) from public, anon, authenticated;

create or replace function public.source_locked_for_editor(p_source uuid) returns boolean
language sql stable security invoker set search_path='' as $$
  select exists(select 1 from public.event_sources es join public.historical_events e on e.id=es.event_id where es.source_id=p_source and e.workflow_status in ('pending_review','published','hidden'))
  or exists(select 1 from public.media_assets ma where ma.source_id=p_source and public.media_owner_status(ma.event_id,ma.figure_id,ma.location_id) in ('pending_review','published','hidden'))
  or exists(select 1 from public.figure_sources fs join public.historical_figures f on f.id=fs.figure_id where fs.source_id=p_source and f.workflow_status in ('pending_review','published','hidden'))
  or exists(select 1 from public.figure_story_sources ss join public.figure_stories s on s.id=ss.story_id join public.historical_figures f on f.id=s.figure_id where ss.source_id=p_source and f.workflow_status in ('pending_review','published','hidden'))
  or exists(select 1 from public.figure_media_evidence me join public.historical_figures f on f.id=me.figure_id where (me.identity_source_id=p_source or me.usage_source_id=p_source) and f.workflow_status in ('pending_review','published','hidden'))
  or exists(select 1 from public.figure_localities fl join public.historical_figures f on f.id=fl.figure_id where fl.primary_source_id=p_source and f.workflow_status in ('pending_review','published','hidden'))
$$;

create function private.local_hero_lock_writes() returns trigger
language plpgsql security definer set search_path='' as $$
begin perform pg_advisory_xact_lock(18012,3401); return null; end $$;
revoke all on function private.local_hero_lock_writes() from public, anon, authenticated;

create function private.local_hero_guard_mutation() returns trigger
language plpgsql security definer set search_path='' as $$
declare o jsonb; n jsonb; f public.historical_figures; actor public.staff_role; protected boolean; changes boolean; item record;
begin
  if tg_op<>'INSERT' then o:=to_jsonb(old); end if;
  if tg_op<>'DELETE' then n:=to_jsonb(new); end if;
  -- Only an actual database-owner session (migration/test setup) may bypass actor checks.
  -- SET ROLE authenticated/anon does not take this branch, even in a psql session.
  if current_setting('role') in ('none','postgres') and session_user in ('postgres','supabase_admin') and auth.uid() is null then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  actor:=public.current_staff_role();
  if tg_table_name='historical_figures' and not coalesce((o->>'is_local_hero')::boolean,false) and not coalesce((n->>'is_local_hero')::boolean,false) then return coalesce(new,old); end if;
  for f in select hf.* from public.historical_figures hf where hf.is_local_hero and hf.id in (
    select * from private.local_hero_owners(tg_table_name,o) union select * from private.local_hero_owners(tg_table_name,n)
  ) loop
    if actor is null or auth.uid() is null then raise exception using errcode='LH002', message='FORBIDDEN'; end if;
    protected:=f.workflow_status in ('pending_review','published','hidden');
    if tg_table_name='historical_figures' then
      if tg_op='DELETE' then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      if n->'is_local_hero'<>'true'::jsonb or n->'id' is distinct from o->'id' then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      if n->'local_hero_revision' is distinct from o->'local_hero_revision' or n->'local_hero_search_text' is distinct from o->'local_hero_search_text' then raise exception using errcode='LH002',message='REVISION_FORGERY'; end if;
      changes:=(n-array['workflow_status','review_note','updated_at']) is distinct from (o-array['workflow_status','review_note','updated_at']);
      if n=o then return new; end if; -- parent touch; derived fields run after reviewer guard
      if changes and (protected or actor not in ('editor','system_admin')) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      if n->>'workflow_status' is distinct from o->>'workflow_status' then
        if not (
          (actor in ('editor','system_admin') and f.workflow_status in ('draft','needs_revision') and n->>'workflow_status' in ('draft','needs_revision','pending_review'))
          or (actor in ('reviewer','system_admin') and ((f.workflow_status='pending_review' and n->>'workflow_status' in ('published','needs_revision')) or (f.workflow_status='published' and n->>'workflow_status'='hidden') or (f.workflow_status='hidden' and n->>'workflow_status'='published')))
          or (actor='system_admin' and n->>'workflow_status'='draft')
        ) then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
      elsif not changes and protected then
        raise exception using errcode='LH003',message='INVALID_TRANSITION';
      end if;
    elsif tg_table_name='figure_stories' and tg_op='UPDATE' and (n-array['workflow_status','review_note','updated_at'])=(o-array['workflow_status','review_note','updated_at']) then
      if not (
        (actor in ('editor','system_admin') and not protected and o->>'workflow_status' in ('draft','needs_revision') and n->>'workflow_status'='pending_review')
        or (actor in ('reviewer','system_admin') and ((o->>'workflow_status'='pending_review' and n->>'workflow_status' in ('published','needs_revision')) or (o->>'workflow_status'='published' and n->>'workflow_status'='hidden') or (o->>'workflow_status'='hidden' and n->>'workflow_status'='published')))
        or (actor='system_admin' and n->>'workflow_status'='draft')
        or (actor in ('editor','system_admin') and not protected and o->>'workflow_status' in ('draft','needs_revision') and n->>'workflow_status'=o->>'workflow_status')
      ) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
    else
      if protected or actor not in ('editor','system_admin') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      if tg_table_name='figure_story_sources' and exists(select 1 from public.figure_stories st where st.id=coalesce((n->>'story_id')::uuid,(o->>'story_id')::uuid) and st.workflow_status not in ('draft','needs_revision')) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      if tg_table_name='figure_stories' and (coalesce(o->>'workflow_status','draft') not in ('draft','needs_revision') or n->>'workflow_status'<>'draft' and tg_op='INSERT') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
    end if;
  end loop;
  if tg_table_name='historical_figures' and tg_op='INSERT' and (n->>'is_local_hero')::boolean then
    if actor not in ('editor','system_admin') or actor is null or n->>'workflow_status'<>'draft' or n->>'local_hero_revision'<>'0' or n->>'local_hero_search_text'<>'' then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  elsif tg_table_name='historical_figures' and tg_op='UPDATE' and not (o->>'is_local_hero')::boolean and (n->>'is_local_hero')::boolean then
    if actor not in ('editor','system_admin') or actor is null or o->>'workflow_status' not in ('draft','needs_revision') or n->>'workflow_status' not in ('draft','needs_revision') or n->'local_hero_revision' is distinct from o->'local_hero_revision' or n->'local_hero_search_text' is distinct from o->'local_hero_search_text' then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  end if;
  if tg_op='UPDATE' and tg_table_name<>'sources' then
    if (o->'id' is distinct from n->'id') or (o->'figure_id' is distinct from n->'figure_id') or (o->'story_id' is distinct from n->'story_id') or (o->'media_id' is distinct from n->'media_id') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  end if;
  if tg_table_name in ('figure_sources','figure_localities','figure_stories','figure_story_sources','figure_media_evidence') or (tg_table_name='historical_figures' and coalesce((n->>'is_local_hero')::boolean,false)) then
    if actor is null or auth.uid() is null then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
    if tg_op='INSERT' and tg_table_name<>'historical_figures' and not exists(select 1 from private.local_hero_owners(tg_table_name,n) i join public.historical_figures hf on hf.id=i where hf.is_local_hero) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
    for item in select key,value from jsonb_each_text(n) where jsonb_typeof(n->key)='string' loop
      if item.value<>normalize(item.value,NFC) or translate(item.value,E'\n\r\t','') ~ '[[:cntrl:]]' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    end loop;
    if tg_table_name='figure_stories' and n->>'body' ~* '(<[!/]?[a-z]|!\[|\]\([[:space:]]*(javascript|data|vbscript):)' or tg_table_name='historical_figures' and n->>'biography' ~* '(<[!/]?[a-z]|!\[|\]\([[:space:]]*(javascript|data|vbscript):)' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;
revoke all on function private.local_hero_guard_mutation() from public, anon, authenticated;

create function private.local_hero_derive_fields() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  if new.is_local_hero then
    new.local_hero_revision:=case when tg_op='INSERT' then 1 else old.local_hero_revision+1 end;
    new.local_hero_search_text:=public.local_hero_fold(new.name||' '||array_to_string(new.catalog_aliases,' ')||' '||coalesce(new.contribution_summary,''));
  end if;
  return new;
end $$;
revoke all on function private.local_hero_derive_fields() from public, anon, authenticated;
create trigger trg_zz_lh_derive before insert or update on public.historical_figures for each row execute function private.local_hero_derive_fields();

create function private.local_hero_touch_parent() returns trigger
language plpgsql security definer set search_path='' as $$
declare fid uuid;
begin
  for fid in select * from private.local_hero_owners(tg_table_name,case when tg_op<>'INSERT' then to_jsonb(old) end)
    union select * from private.local_hero_owners(tg_table_name,case when tg_op<>'DELETE' then to_jsonb(new) end) loop
    update public.historical_figures set name=name where id=fid and is_local_hero;
  end loop;
  return null;
end $$;
revoke all on function private.local_hero_touch_parent() from public, anon, authenticated;
create function private.local_hero_assert_graph(p_figure_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare f public.historical_figures; s record; c record; m record; src record; k text; paragraph text; clean text; wc integer;
begin
  select * into f from public.historical_figures where id=p_figure_id;
  if not found then return; end if;
  if not f.is_local_hero then
    if exists(select 1 from public.figure_sources where figure_id=f.id) or exists(select 1 from public.figure_stories where figure_id=f.id) or exists(select 1 from public.figure_localities where figure_id=f.id) or exists(select 1 from public.figure_media_evidence where figure_id=f.id) then raise exception using errcode='23514',message='LH_INVALID_PARENT'; end if;
    return;
  end if;
  if (select count(*) from public.figure_sources where figure_id=f.id)>300 or (select count(*) from public.figure_localities where figure_id=f.id)>136 or (select count(*) from public.figure_stories where figure_id=f.id)>30 or (select count(*) from public.figure_media_evidence where figure_id=f.id)>50
    or exists(select 1 from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id where st.figure_id=f.id group by ss.story_id having count(*)>300)
  then raise exception using errcode='23514',message='LH_GRAPH_BOUND'; end if;
  if exists(select 1 from public.figure_sources where figure_id=f.id group by claim_key having count(distinct (claim_text,certainty,uncertainty_note))>1)
    or exists(select 1 from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id where st.figure_id=f.id group by story_id,claim_key having count(distinct (claim_text,certainty,uncertainty_note))>1)
    or exists(select 1 from public.figure_localities fl join public.figure_sources fs on (fs.figure_id,fs.claim_key,fs.source_id)=(fl.figure_id,fl.claim_key,fl.primary_source_id) where fl.figure_id=f.id and fl.certainty<>fs.certainty)
  then raise exception using errcode='23514',message='LH_CLAIM_GROUP'; end if;
  if exists(select 1 from public.figure_stories where figure_id=f.id and ((workflow_status='published' and f.workflow_status<>'published') or (workflow_status='pending_review' and f.workflow_status<>'pending_review'))) then raise exception using errcode='LH001',message='PRIMARY_STORY_REQUIRED'; end if;

  -- An accepted image must be authentic/evidenced even while its parent remains draft.
  for m in select me.*,ma.media_type,ma.era,ma.caption,ma.alt_text,ma.width,ma.height,ma.photographer,ma.source_page_url,ma.file_url,ma.is_reenactment,ma.is_colorized,ma.license,ma.license_url
    from public.figure_media_evidence me join public.media_assets ma on ma.id=me.media_id and ma.figure_id=me.figure_id where me.figure_id=f.id and me.decision='accepted' loop
    if m.media_type<>'image' or m.era not in ('historical','illustration') or coalesce(length(btrim(m.caption)),0)=0 or coalesce(length(btrim(m.alt_text)),0)=0
      or coalesce(m.width,0)<=0 or coalesce(m.height,0)<=0 or coalesce(length(btrim(m.photographer)),0)=0
      or coalesce(m.source_page_url,'') !~ '^https://[^/@[:space:]?#]+([/?#][^[:space:]]*)?$'
      or coalesce(m.file_url,'') !~ '^https://[^/@[:space:]?#]+([/?#][^[:space:]]*)?$'
      or m.file_url ~* '\.(exe|svg|pdf|html?|js|zip)([?#].*)?$'
      or (m.depiction_kind='portrait' and (m.era<>'historical' or m.is_reenactment or m.is_colorized))
      or (m.depiction_kind='historical_context' and position('Tư liệu bối cảnh, không phải chân dung' in m.caption)=0)
      or (m.usage_basis='open_license' and (coalesce(length(btrim(m.license)),0)=0 or coalesce(m.license_url,'') !~ '^https://[^/@[:space:]?#]+([/?#][^[:space:]]*)?$'))
      or (m.usage_basis='coursework_reference' and (position('LH-1.0.0' in coalesce(m.usage_note,''))=0 and position('docs/audits/2026-10-25-journey-popup-media-sources.md' in coalesce(m.usage_note,''))=0 or position(m.source_page_url in coalesce(m.usage_note,''))=0))
    then raise exception using errcode='LH001',message='IMAGE_IDENTITY'; end if;
  end loop;
  if f.workflow_status not in ('pending_review','published') then return; end if;
  if f.workflow_status='published' and f.review_note is not null then raise exception using errcode='LH001',message='INTERNAL_NOTE'; end if;
  if concat_ws(' ',f.name,f.biography,f.contribution_summary,array_to_string(f.catalog_aliases,' ')) ~* '\m(TODO|FIXME)\M' then raise exception using errcode='LH001',message='INTERNAL_NOTE'; end if;
  if exists(select 1 from public.figure_sources fs where fs.figure_id=f.id and concat_ws(' ',fs.claim_text,fs.locator,fs.scope_note,fs.uncertainty_note) ~* '\m(TODO|FIXME)\M')
    or exists(select 1 from public.figure_localities fl where fl.figure_id=f.id and concat_ws(' ',fl.historical_place_label,fl.explanation,fl.uncertainty_note) ~* '\m(TODO|FIXME)\M')
    or exists(select 1 from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id where st.figure_id=f.id and st.workflow_status=f.workflow_status and concat_ws(' ',ss.claim_text,ss.locator,ss.scope_note,ss.uncertainty_note) ~* '\m(TODO|FIXME)\M')
    or exists(select 1 from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id where me.figure_id=f.id and me.decision='accepted' and concat_ws(' ',ma.caption,ma.alt_text,ma.photographer,ma.license,me.usage_note) ~* '\m(TODO|FIXME)\M')
  then raise exception using errcode='LH001',message='INTERNAL_NOTE'; end if;
  foreach k in array array['identity','contribution','period'] loop
    if not exists(select 1 from public.figure_sources fs where fs.figure_id=f.id and fs.claim_key=k and fs.certainty='verified') then
      raise exception using errcode='LH001',message=case k when 'identity' then 'IDENTITY_SOURCE_REQUIRED' when 'contribution' then 'CONTRIBUTION_SOURCE_REQUIRED' else 'PERIOD_SOURCE_REQUIRED' end;
    end if;
  end loop;
  if coalesce(length(btrim(f.contribution_summary)),0)=0 or f.contribution_start_year is null or f.contribution_end_year is null or f.contribution_start_year>1975 or f.contribution_end_year<1858 then raise exception using errcode='LH001',message='PERIOD_OUT_OF_SCOPE'; end if;
  foreach k in array array[case when coalesce(length(btrim(f.biography)),0)>0 then 'biography' end,case when f.birth_year is not null then 'birth_year' end,case when f.death_year is not null then 'death_year' end,case when cardinality(f.catalog_aliases)>0 then 'aliases' end] loop
    if k is not null and not exists(select 1 from public.figure_sources fs where fs.figure_id=f.id and fs.claim_key=k and (k<>'aliases' or fs.certainty='verified')) then raise exception using errcode='LH001',message='DISPLAYED_CLAIM_SOURCE_REQUIRED'; end if;
  end loop;
  if not exists(select 1 from public.figure_localities fl join public.figure_sources fs on (fs.figure_id,fs.claim_key,fs.source_id)=(fl.figure_id,fl.claim_key,fl.primary_source_id) where fl.figure_id=f.id and fl.relationship_kind in ('birthplace','home_origin','activity') and fl.certainty='verified' and fs.certainty='verified') then raise exception using errcode='LH001',message='LOCALITY_MAPPING_REQUIRED'; end if;
  if (select count(*) from public.figure_stories where figure_id=f.id and is_primary and workflow_status=f.workflow_status)<>1 then raise exception using errcode='LH001',message='PRIMARY_STORY_REQUIRED'; end if;
  if not exists(select 1 from public.figure_media_evidence where figure_id=f.id and decision='accepted') then raise exception using errcode='LH001',message='IMAGE_REQUIRED'; end if;

  for src in select so.* from public.sources so where so.id in (
    select source_id from public.figure_sources where figure_id=f.id
    union select ss.source_id from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id where st.figure_id=f.id and st.workflow_status=f.workflow_status
    union select identity_source_id from public.figure_media_evidence where figure_id=f.id and decision='accepted'
    union select usage_source_id from public.figure_media_evidence where figure_id=f.id and decision='accepted'
    union select ma.source_id from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id where me.figure_id=f.id and me.decision='accepted'
  ) loop
    if concat_ws(' ',src.title,src.author_org,src.publisher,src.citation) ~* '\m(TODO|FIXME)\M' then raise exception using errcode='LH001',message='INTERNAL_NOTE'; end if;
    if length(btrim(src.title))=0 or length(btrim(src.citation))=0 or coalesce(length(btrim(coalesce(nullif(btrim(src.author_org),''),src.publisher))),0)=0 or src.accessed_at is null
      or (src.url is not null and src.url !~ '^https://[^/@[:space:]?#]+([/?#][^[:space:]]*)?$')
    then raise exception using errcode='LH001',message='SOURCE_METADATA'; end if;
  end loop;
  -- Distinct origins are necessary, not a historian's certification of independence.
  for c in select fs.claim_key,count(distinct coalesce(nullif(lower(btrim(so.author_org)),''),nullif(lower(btrim(so.publisher)),''),split_part(so.url,'/',3))) origins
    from public.figure_sources fs join public.sources so on so.id=fs.source_id where fs.figure_id=f.id and fs.certainty='disputed' group by fs.claim_key
    union all select ss.claim_key,count(distinct coalesce(nullif(lower(btrim(so.author_org)),''),nullif(lower(btrim(so.publisher)),''),split_part(so.url,'/',3))) from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id join public.sources so on so.id=ss.source_id where st.figure_id=f.id and st.workflow_status=f.workflow_status and ss.certainty='disputed' group by st.id,ss.claim_key loop
    if c.origins<2 then raise exception using errcode='LH001',message='INDEPENDENT_SOURCES_REQUIRED'; end if;
  end loop;
  for s in select * from public.figure_stories where figure_id=f.id and workflow_status=f.workflow_status loop
    if s.title||s.summary||s.body ~* '\m(TODO|FIXME)\M' then raise exception using errcode='LH001',message='INTERNAL_NOTE'; end if;
    if length(btrim(s.summary))=0 or not exists(select 1 from public.figure_story_sources where story_id=s.id) then raise exception using errcode='LH001',message='STORY_SOURCE_REQUIRED'; end if;
    clean:=regexp_replace(s.body,'\[\[cite:[^]]+\]\]','','g');
    if position('[[cite:' in clean)>0 then raise exception using errcode='LH001',message='CITATION_MARKER_INVALID'; end if;
    clean:=regexp_replace(replace(replace(clean,'**',''),'__',''),'(^|\n)[[:space:]]*#{1,6}[[:space:]]+','\1','g');
    wc:=cardinality(regexp_split_to_array(btrim(clean),'[[:space:]]+'));
    if s.is_primary and (wc<350 or wc>700) then raise exception using errcode='LH001',message='STORY_LENGTH'; end if;
    for c in select a[1] key from regexp_matches(s.body,'\[\[cite:([^]]+)\]\]','g') a loop
      if not exists(select 1 from public.figure_story_sources where story_id=s.id and claim_key=c.key) then raise exception using errcode='LH001',message='CITATION_MARKER_INVALID'; end if;
    end loop;
    for paragraph in select regexp_split_to_table(s.body,E'\n[[:space:]]*\n') loop
      if btrim(paragraph)<>'' and paragraph !~ '^#{1,6} ' and paragraph !~ '\[\[cite:[^]]+\]\]' then raise exception using errcode='LH001',message='STORY_SOURCE_REQUIRED'; end if;
    end loop;
  end loop;
end $$;
revoke all on function private.local_hero_assert_graph(uuid) from public, anon, authenticated;

create function private.local_hero_check_deferred() returns trigger
language plpgsql security definer set search_path='' as $$
declare fid uuid;
begin
  for fid in select * from private.local_hero_owners(tg_table_name,case when tg_op<>'INSERT' then to_jsonb(old) end)
    union select * from private.local_hero_owners(tg_table_name,case when tg_op<>'DELETE' then to_jsonb(new) end) loop
    perform private.local_hero_assert_graph(fid);
  end loop;
  return null;
end $$;
revoke all on function private.local_hero_check_deferred() from public, anon, authenticated;
do $$
declare t text;
begin
  foreach t in array array['historical_figures','sources','media_assets','figure_sources','figure_localities','figure_stories','figure_story_sources','figure_media_evidence'] loop
    execute format('create trigger trg_lh_lock_writes before insert or update or delete on public.%I for each statement execute function private.local_hero_lock_writes()',t);
    execute format('create trigger trg_00_lh_guard before insert or update or delete on public.%I for each row execute function private.local_hero_guard_mutation()',t);
    execute format('create constraint trigger trg_lh_graph_integrity after insert or update or delete on public.%I deferrable initially deferred for each row execute function private.local_hero_check_deferred()',t);
    if t<>'historical_figures' then execute format('create trigger trg_lh_touch_parent after insert or update or delete on public.%I for each row execute function private.local_hero_touch_parent()',t); end if;
  end loop;
end $$;

create function public.local_hero_save_graph(p_command jsonb) returns jsonb
language plpgsql volatile security invoker set search_path='' as $command$

declare f public.historical_figures; fid uuid; actor public.staff_role; r jsonb; s jsonb; e jsonb; reason text; target public.content_workflow_status; selected uuid[]; code text; message text; revision text; readiness jsonb := '{"blocking":[],"warnings":[]}'::jsonb;
begin
  perform pg_advisory_xact_lock(18012,3401);
  set constraints all deferred;
  if auth.uid() is null then raise exception using errcode='LH004',message='UNAUTHENTICATED'; end if;
  actor:=public.current_staff_role();
  if actor is null then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if actor not in ('editor','system_admin') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision','figure','sources','localities','stories','mediaEvidence']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision','figure','sources','localities','stories','mediaEvidence'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  r:=p_command->'figure';
  if jsonb_typeof(r) is distinct from 'object' or not (r ?& array['name','slug','otherNames','birthYear','deathYear','biography','isLocalHero','contributionSummary','contributionStartYear','contributionEndYear','catalogAliases']) or exists(select 1 from jsonb_object_keys(r) k where k<>all(array['name','slug','otherNames','birthYear','deathYear','biography','isLocalHero','contributionSummary','contributionStartYear','contributionEndYear','catalogAliases'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if r->'isLocalHero' is distinct from 'true'::jsonb or jsonb_typeof(r->'name')<>'string' or length(btrim(r->>'name')) not between 1 and 200 or jsonb_typeof(r->'slug')<>'string' or length(r->>'slug')>160 or r->>'slug' !~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    or jsonb_typeof(r->'otherNames') not in ('string','null') or jsonb_typeof(r->'biography') not in ('string','null') or jsonb_typeof(r->'contributionSummary') not in ('string','null') or jsonb_typeof(r->'catalogAliases')<>'array'
    or exists(select 1 from jsonb_array_elements(r->'catalogAliases') a where jsonb_typeof(a)<>'string')
    or exists(select 1 from jsonb_each(r) v where v.key in ('birthYear','deathYear','contributionStartYear','contributionEndYear') and (jsonb_typeof(v.value) not in ('null','number') or jsonb_typeof(v.value)='number' and v.value::text !~ '^[0-9]+$')) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if jsonb_typeof(p_command->'sources')<>'array' or jsonb_array_length(p_command->'sources')>300 or jsonb_typeof(p_command->'localities')<>'array' or jsonb_array_length(p_command->'localities')>136 or jsonb_typeof(p_command->'stories')<>'array' or jsonb_array_length(p_command->'stories')>30 or jsonb_typeof(p_command->'mediaEvidence')<>'array' or jsonb_array_length(p_command->'mediaEvidence')>50 then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if p_command->'figureId'='null'::jsonb and p_command->'expectedRevision'='null'::jsonb then
    insert into public.historical_figures(name,slug,is_local_hero) values(r->>'name',r->>'slug',true) returning id into fid;
  else

  if not (p_command ?& array['figureId','expectedRevision']) or jsonb_typeof(p_command->'figureId')<>'string' or jsonb_typeof(p_command->'expectedRevision')<>'string'
    or p_command->>'expectedRevision' !~ '^(0|[1-9][0-9]{0,18})$' or length(p_command->>'expectedRevision')=19 and (p_command->>'expectedRevision') collate "C">'9223372036854775807' collate "C" then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  fid:=(p_command->>'figureId')::uuid;
  select * into f from public.historical_figures where id=fid for update;
  if not found then raise exception using errcode='LH005',message='NOT_FOUND'; end if;
  if not f.is_local_hero then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  revision:=f.local_hero_revision::text;
  if f.local_hero_revision<>(p_command->>'expectedRevision')::bigint then raise exception using errcode='40001',message='STALE'; end if;

    if f.workflow_status not in ('draft','needs_revision') then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  end if;
  -- Preflight all child IDs before writing or ON CONFLICT, including OLD ownership.
  if exists(select 1 from public.figure_stories st where st.figure_id=fid and st.workflow_status not in ('draft','needs_revision') and not exists(select 1 from jsonb_array_elements(p_command->'stories') x where (x->>'id')::uuid=st.id)) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;

  if exists(select 1 from jsonb_array_elements(p_command->'stories') x join public.figure_stories st on st.id=(x->>'id')::uuid where st.figure_id<>fid)
    or exists(select 1 from jsonb_array_elements(p_command->'localities') x join public.figure_localities fl on fl.id=(x->>'id')::uuid where fl.figure_id<>fid)
    or exists(select 1 from jsonb_array_elements(p_command->'mediaEvidence') x left join public.media_assets ma on ma.id=(x->>'mediaId')::uuid where ma.id is null or ma.figure_id is distinct from fid)
  then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if exists(select 1 from jsonb_array_elements(p_command->'stories') x group by x->>'id' having count(*)>1) or exists(select 1 from jsonb_array_elements(p_command->'localities') x group by x->>'id' having count(*)>1) or exists(select 1 from jsonb_array_elements(p_command->'mediaEvidence') x group by x->>'mediaId' having count(*)>1) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if exists(select 1 from (
    select (x->>'id')::uuid id from jsonb_array_elements(p_command->'stories') x
    union all select (x->>'id')::uuid from jsonb_array_elements(p_command->'localities') x
    union all select (x->>'mediaId')::uuid from jsonb_array_elements(p_command->'mediaEvidence') x
  ) ids group by id having count(*)>1) or exists(select 1 from jsonb_array_elements(p_command->'sources') x group by x->>'claimKey',(x->>'sourceId')::uuid having count(*)>1) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  update public.historical_figures set name=r->>'name',slug=r->>'slug',other_names=r->>'otherNames',birth_year=(r->>'birthYear')::integer,death_year=(r->>'deathYear')::integer,biography=r->>'biography',is_local_hero=true,contribution_summary=r->>'contributionSummary',contribution_start_year=(r->>'contributionStartYear')::integer,contribution_end_year=(r->>'contributionEndYear')::integer,catalog_aliases=array(select jsonb_array_elements_text(r->'catalogAliases')) where id=fid;
  for e in select * from jsonb_array_elements(p_command->'sources') loop

  if jsonb_typeof(e) is distinct from 'object' or not (e ?& array['claimKey','sourceId','claimText','locator','scopeNote','certainty','uncertaintyNote']) or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['claimKey','sourceId','claimText','locator','scopeNote','certainty','uncertaintyNote'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if jsonb_typeof(e->'claimKey')<>'string' or jsonb_typeof(e->'sourceId')<>'string' or jsonb_typeof(e->'claimText')<>'string' or jsonb_typeof(e->'locator')<>'string' or jsonb_typeof(e->'scopeNote')<>'string' or jsonb_typeof(e->'certainty')<>'string' or jsonb_typeof(e->'uncertaintyNote') not in ('null','string') then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

    insert into public.figure_sources values(fid,e->>'claimKey',(e->>'sourceId')::uuid,e->>'claimText',e->>'locator',e->>'scopeNote',e->>'certainty',e->>'uncertaintyNote')
      on conflict(figure_id,claim_key,source_id) do update set claim_text=excluded.claim_text,locator=excluded.locator,scope_note=excluded.scope_note,certainty=excluded.certainty,uncertainty_note=excluded.uncertainty_note;
  end loop;
  update public.figure_stories st set is_primary=false where st.figure_id=fid and st.is_primary and not exists(select 1 from jsonb_array_elements(p_command->'stories') x where (x->>'id')::uuid=st.id and x->'isPrimary'='true'::jsonb);
  for s in select * from jsonb_array_elements(p_command->'stories') loop
    if jsonb_typeof(s) is distinct from 'object' or not (s ?& array['id','slug','title','summary','body','sortOrder','isPrimary','sources']) or exists(select 1 from jsonb_object_keys(s) k where k<>all(array['id','slug','title','summary','body','sortOrder','isPrimary','sources'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if jsonb_typeof(s->'id')<>'string' or jsonb_typeof(s->'slug')<>'string' or jsonb_typeof(s->'title')<>'string' or jsonb_typeof(s->'summary')<>'string' or jsonb_typeof(s->'body')<>'string' or jsonb_typeof(s->'sortOrder')<>'number' or s->>'sortOrder' !~ '^[0-9]+$' or jsonb_typeof(s->'isPrimary')<>'boolean' or jsonb_typeof(s->'sources')<>'array' or jsonb_array_length(s->'sources')>300 then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if exists(select 1 from public.figure_stories st where st.id=(s->>'id')::uuid and st.workflow_status not in ('draft','needs_revision')) then
      if not exists(select 1 from public.figure_stories st where st.id=(s->>'id')::uuid and st.slug=s->>'slug' and st.title=s->>'title' and st.summary=s->>'summary' and st.body=s->>'body' and st.sort_order=(s->>'sortOrder')::integer and st.is_primary=(s->>'isPrimary')::boolean
        and coalesce((select jsonb_agg(v order by v->>'claimKey',v->>'sourceId') from (select jsonb_build_object('claimKey',ss.claim_key,'sourceId',ss.source_id,'claimText',ss.claim_text,'locator',ss.locator,'scopeNote',ss.scope_note,'certainty',ss.certainty,'uncertaintyNote',ss.uncertainty_note) v from public.figure_story_sources ss where ss.story_id=st.id) a),'[]'::jsonb)=coalesce((select jsonb_agg(v order by v->>'claimKey',v->>'sourceId') from jsonb_array_elements(s->'sources') v),'[]'::jsonb)) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
      continue;
    end if;
    insert into public.figure_stories(id,figure_id,slug,title,summary,body,sort_order,is_primary) values((s->>'id')::uuid,fid,s->>'slug',s->>'title',s->>'summary',s->>'body',(s->>'sortOrder')::integer,(s->>'isPrimary')::boolean)
      on conflict(id) do update set slug=excluded.slug,title=excluded.title,summary=excluded.summary,body=excluded.body,sort_order=excluded.sort_order,is_primary=excluded.is_primary,updated_at=now();
    for e in select * from jsonb_array_elements(s->'sources') loop

  if jsonb_typeof(e) is distinct from 'object' or not (e ?& array['claimKey','sourceId','claimText','locator','scopeNote','certainty','uncertaintyNote']) or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['claimKey','sourceId','claimText','locator','scopeNote','certainty','uncertaintyNote'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if jsonb_typeof(e->'claimKey')<>'string' or jsonb_typeof(e->'sourceId')<>'string' or jsonb_typeof(e->'claimText')<>'string' or jsonb_typeof(e->'locator')<>'string' or jsonb_typeof(e->'scopeNote')<>'string' or jsonb_typeof(e->'certainty')<>'string' or jsonb_typeof(e->'uncertaintyNote') not in ('null','string') then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

      insert into public.figure_story_sources values((s->>'id')::uuid,e->>'claimKey',(e->>'sourceId')::uuid,e->>'claimText',e->>'locator',e->>'scopeNote',e->>'certainty',e->>'uncertaintyNote')
        on conflict(story_id,claim_key,source_id) do update set claim_text=excluded.claim_text,locator=excluded.locator,scope_note=excluded.scope_note,certainty=excluded.certainty,uncertainty_note=excluded.uncertainty_note;
    end loop;
  end loop;
  for e in select * from jsonb_array_elements(p_command->'localities') loop
    if jsonb_typeof(e) is distinct from 'object' or not (e ?& array['id','localityCode','kind','historicalPlaceLabel','explanation','claimKey','primarySourceId','certainty','uncertaintyNote']) or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['id','localityCode','kind','historicalPlaceLabel','explanation','claimKey','primarySourceId','certainty','uncertaintyNote'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if exists(select 1 from jsonb_each(e) v where v.key<>'uncertaintyNote' and jsonb_typeof(v.value)<>'string' or v.key='uncertaintyNote' and jsonb_typeof(v.value) not in ('string','null')) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    insert into public.figure_localities(id,figure_id,locality_code,relationship_kind,historical_place_label,explanation,claim_key,primary_source_id,certainty,uncertainty_note) values((e->>'id')::uuid,fid,e->>'localityCode',e->>'kind',e->>'historicalPlaceLabel',e->>'explanation',e->>'claimKey',(e->>'primarySourceId')::uuid,e->>'certainty',e->>'uncertaintyNote')
      on conflict(id) do update set locality_code=excluded.locality_code,relationship_kind=excluded.relationship_kind,historical_place_label=excluded.historical_place_label,explanation=excluded.explanation,claim_key=excluded.claim_key,primary_source_id=excluded.primary_source_id,certainty=excluded.certainty,uncertainty_note=excluded.uncertainty_note;
  end loop;
  for e in select * from jsonb_array_elements(p_command->'mediaEvidence') loop
    if jsonb_typeof(e) is distinct from 'object' or not (e ?& array['mediaId','depictionKind','decision','identitySourceId','identityLocator','identityCertainty','usageBasis','usageSourceId','usageLocator','usageNote','checkedAt']) or exists(select 1 from jsonb_object_keys(e) k where k<>all(array['mediaId','depictionKind','decision','identitySourceId','identityLocator','identityCertainty','usageBasis','usageSourceId','usageLocator','usageNote','checkedAt'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if exists(select 1 from jsonb_each(e) v where v.key<>all(array['usageSourceId','usageLocator','usageNote','checkedAt']) and jsonb_typeof(v.value)<>'string' or v.key=any(array['usageSourceId','usageLocator','usageNote','checkedAt']) and jsonb_typeof(v.value) not in ('string','null'))
      or e->'checkedAt'<>'null'::jsonb and e->>'checkedAt' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?Z$'
    then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    insert into public.figure_media_evidence values((e->>'mediaId')::uuid,fid,e->>'depictionKind',e->>'decision',(e->>'identitySourceId')::uuid,e->>'identityLocator',e->>'identityCertainty',e->>'usageBasis',(e->>'usageSourceId')::uuid,e->>'usageLocator',e->>'usageNote',(e->>'checkedAt')::timestamptz)
      on conflict(media_id) do update set depiction_kind=excluded.depiction_kind,decision=excluded.decision,identity_source_id=excluded.identity_source_id,identity_locator=excluded.identity_locator,identity_certainty=excluded.identity_certainty,usage_basis=excluded.usage_basis,usage_source_id=excluded.usage_source_id,usage_locator=excluded.usage_locator,usage_note=excluded.usage_note,checked_at=excluded.checked_at;
  end loop;
  delete from public.figure_localities fl where fl.figure_id=fid and not exists(select 1 from jsonb_array_elements(p_command->'localities') x where (x->>'id')::uuid=fl.id);
  delete from public.figure_media_evidence me where me.figure_id=fid and not exists(select 1 from jsonb_array_elements(p_command->'mediaEvidence') x where (x->>'mediaId')::uuid=me.media_id);
  delete from public.figure_story_sources ss using public.figure_stories st where st.id=ss.story_id and st.figure_id=fid and st.workflow_status in ('draft','needs_revision') and not exists(select 1 from jsonb_array_elements(p_command->'stories') x cross join lateral jsonb_array_elements(x->'sources') y where (x->>'id')::uuid=ss.story_id and y->>'claimKey'=ss.claim_key and (y->>'sourceId')::uuid=ss.source_id);
  delete from public.figure_stories st where st.figure_id=fid and not exists(select 1 from jsonb_array_elements(p_command->'stories') x where (x->>'id')::uuid=st.id);
  delete from public.figure_sources fs where fs.figure_id=fid and not exists(select 1 from jsonb_array_elements(p_command->'sources') x where x->>'claimKey'=fs.claim_key and (x->>'sourceId')::uuid=fs.source_id);
  -- Draft success is deliberately separate from structural readiness; missing evidence stays draft.
  readiness:=jsonb_build_object('blocking',coalesce((select jsonb_agg(jsonb_build_object('code',v.code,'path','graph','message','Cần hoàn thiện chứng cứ trước khi gửi duyệt.')) from (
    select 'IDENTITY_SOURCE_REQUIRED' code where not exists(select 1 from public.figure_sources where figure_id=fid and claim_key='identity' and certainty='verified')
    union all select 'CONTRIBUTION_SOURCE_REQUIRED' where not exists(select 1 from public.figure_sources where figure_id=fid and claim_key='contribution' and certainty='verified')
    union all select 'PERIOD_SOURCE_REQUIRED' where not exists(select 1 from public.figure_sources where figure_id=fid and claim_key='period' and certainty='verified')
    union all select 'LOCALITY_MAPPING_REQUIRED' where not exists(select 1 from public.figure_localities where figure_id=fid and certainty='verified' and relationship_kind<>'commemoration')
    union all select 'PRIMARY_STORY_REQUIRED' where not exists(select 1 from public.figure_stories where figure_id=fid and is_primary)
    union all select 'IMAGE_REQUIRED' where not exists(select 1 from public.figure_media_evidence where figure_id=fid and decision='accepted')
    union all select 'PERIOD_OUT_OF_SCOPE' where not exists(select 1 from public.historical_figures hf where hf.id=fid and hf.contribution_summary is not null and hf.contribution_start_year<=1975 and hf.contribution_end_year>=1858)
    union all select 'DISPLAYED_CLAIM_SOURCE_REQUIRED' where exists(select 1 from public.historical_figures hf cross join lateral unnest(array[case when coalesce(length(btrim(hf.biography)),0)>0 then 'biography' end,case when hf.birth_year is not null then 'birth_year' end,case when hf.death_year is not null then 'death_year' end,case when cardinality(hf.catalog_aliases)>0 then 'aliases' end]) needed(key) where hf.id=fid and needed.key is not null and not exists(select 1 from public.figure_sources fs where fs.figure_id=fid and fs.claim_key=needed.key and (needed.key<>'aliases' or fs.certainty='verified')))
    union all select 'STORY_SOURCE_REQUIRED' where exists(select 1 from public.figure_stories st where st.figure_id=fid and st.is_primary and (length(btrim(st.summary))=0 or not exists(select 1 from public.figure_story_sources ss where ss.story_id=st.id) or exists(select 1 from regexp_split_to_table(st.body,E'\n[[:space:]]*\n') para where btrim(para)<>'' and para !~ '^#{1,6} ' and para !~ '\[\[cite:[^]]+\]\]')))
    union all select 'STORY_LENGTH' where exists(select 1 from public.figure_stories st where st.figure_id=fid and st.is_primary and cardinality(regexp_split_to_array(btrim(regexp_replace(replace(replace(regexp_replace(st.body,'\[\[cite:[^]]+\]\]','','g'),'**',''),'__',''),'(^|\n)[[:space:]]*#{1,6}[[:space:]]+','\1','g')),'[[:space:]]+')) not between 350 and 700)
    union all select 'CITATION_MARKER_INVALID' where exists(select 1 from public.figure_stories st where st.figure_id=fid and st.is_primary and (position('[[cite:' in regexp_replace(st.body,'\[\[cite:[^]]+\]\]','','g'))>0 or exists(select 1 from regexp_matches(st.body,'\[\[cite:([^]]+)\]\]','g') marker where not exists(select 1 from public.figure_story_sources ss where ss.story_id=st.id and ss.claim_key=marker[1]))))
    union all select 'SOURCE_METADATA' where exists(select 1 from public.sources so where so.id in (
      select source_id from public.figure_sources where figure_id=fid
      union select ss.source_id from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id where st.figure_id=fid and st.is_primary
      union select identity_source_id from public.figure_media_evidence where figure_id=fid and decision='accepted'
      union select usage_source_id from public.figure_media_evidence where figure_id=fid and decision='accepted'
      union select ma.source_id from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id where me.figure_id=fid and me.decision='accepted'
    ) and (length(btrim(so.title))=0 or length(btrim(so.citation))=0 or coalesce(length(btrim(coalesce(nullif(btrim(so.author_org),''),so.publisher))),0)=0 or so.accessed_at is null or so.url is not null and so.url !~ '^https://[^/@[:space:]?#]+([/?#][^[:space:]]*)?$'))
    union all select 'INDEPENDENT_SOURCES_REQUIRED' where exists(select 1 from public.figure_sources fs join public.sources so on so.id=fs.source_id where fs.figure_id=fid and fs.certainty='disputed' group by fs.claim_key having count(distinct coalesce(nullif(lower(btrim(so.author_org)),''),nullif(lower(btrim(so.publisher)),''),split_part(so.url,'/',3)))<2)
    union all select 'INDEPENDENT_SOURCES_REQUIRED' where exists(select 1 from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id join public.sources so on so.id=ss.source_id where st.figure_id=fid and st.is_primary and ss.certainty='disputed' group by ss.story_id,ss.claim_key having count(distinct coalesce(nullif(lower(btrim(so.author_org)),''),nullif(lower(btrim(so.publisher)),''),split_part(so.url,'/',3)))<2)
    union all select 'INTERNAL_NOTE' where exists(select 1 from public.historical_figures hf where hf.id=fid and concat_ws(' ',hf.name,hf.biography,hf.contribution_summary,array_to_string(hf.catalog_aliases,' ')) ~* '\m(TODO|FIXME)\M') or exists(select 1 from public.figure_stories st where st.figure_id=fid and st.is_primary and st.title||st.summary||st.body ~* '\m(TODO|FIXME)\M')
  ) v),'[]'::jsonb),'warnings','[]'::jsonb);

  set constraints all immediate;
  select * into f from public.historical_figures where id=fid;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('figureId',f.id,'slug',f.slug,'revision',f.local_hero_revision::text,'workflow',f.workflow_status,'readiness',readiness));
exception when others then
  code:=case sqlstate when 'LH004' then 'UNAUTHENTICATED' when 'LH002' then 'FORBIDDEN' when 'LH005' then 'NOT_FOUND' when 'LH003' then 'INVALID_TRANSITION' when 'LH001' then 'READINESS_FAILED' when '40001' then 'STALE' when '40P01' then 'STALE' when '23505' then 'CONFLICT' when '23503' then 'CONFLICT' when '22023' then 'INVALID_INPUT' when '22P02' then 'INVALID_INPUT' when '22003' then 'INVALID_INPUT' when '23514' then 'INVALID_INPUT' when '23502' then 'INVALID_INPUT' when '42501' then 'FORBIDDEN' else 'DB_UNAVAILABLE' end;
  message:=case code when 'UNAUTHENTICATED' then 'Vui lòng đăng nhập.' when 'FORBIDDEN' then 'Bạn không có quyền thực hiện thao tác này.' when 'NOT_FOUND' then 'Không tìm thấy hồ sơ.' when 'STALE' then 'Hồ sơ đã thay đổi. Hãy tải lại trước khi lưu.' when 'INVALID_TRANSITION' then 'Trạng thái hiện tại không cho phép thao tác này.' when 'READINESS_FAILED' then 'Hồ sơ chưa đủ điều kiện gửi duyệt hoặc công bố.' when 'CONFLICT' then 'Dữ liệu trùng hoặc còn được tham chiếu.' when 'INVALID_INPUT' then 'Dữ liệu không hợp lệ.' else 'Chưa lưu được hồ sơ. Vui lòng thử lại.' end;
  if code='READINESS_FAILED' and sqlerrm in ('IDENTITY_SOURCE_REQUIRED','CONTRIBUTION_SOURCE_REQUIRED','PERIOD_SOURCE_REQUIRED','PERIOD_OUT_OF_SCOPE','DISPLAYED_CLAIM_SOURCE_REQUIRED','LOCALITY_REQUIRED','LOCALITY_MAPPING_REQUIRED','PRIMARY_STORY_REQUIRED','STORY_SOURCE_REQUIRED','STORY_LENGTH','IMAGE_REQUIRED','IMAGE_IDENTITY','IMAGE_USAGE','SOURCE_METADATA','UNCERTAINTY_NOTE_REQUIRED','INDEPENDENT_SOURCES_REQUIRED','INTERNAL_NOTE','CITATION_MARKER_INVALID') then
    readiness:=jsonb_build_object('blocking',jsonb_build_array(jsonb_build_object('code',sqlerrm,'path','graph','message',message)),'warnings','[]'::jsonb);
  else readiness:=null; end if;
  return jsonb_build_object('ok',false,'error',jsonb_build_object('code',code,'message',message,'fieldErrors','{}'::jsonb,'readiness',readiness,'currentRevision',case when code='STALE' then revision else null end));
end
$command$;
revoke all on function public.local_hero_save_graph(jsonb) from public, anon;
grant execute on function public.local_hero_save_graph(jsonb) to authenticated;

create function public.local_hero_submit_graph(p_command jsonb) returns jsonb
language plpgsql volatile security invoker set search_path='' as $command$

declare f public.historical_figures; fid uuid; actor public.staff_role; r jsonb; s jsonb; e jsonb; reason text; target public.content_workflow_status; selected uuid[]; code text; message text; revision text; readiness jsonb := '{"blocking":[],"warnings":[]}'::jsonb;
begin
  perform pg_advisory_xact_lock(18012,3401);
  set constraints all deferred;
  if auth.uid() is null then raise exception using errcode='LH004',message='UNAUTHENTICATED'; end if;
  actor:=public.current_staff_role();
  if actor is null then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if actor not in ('editor','system_admin') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision','storyIds']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision','storyIds'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if not (p_command ?& array['figureId','expectedRevision']) or jsonb_typeof(p_command->'figureId')<>'string' or jsonb_typeof(p_command->'expectedRevision')<>'string'
    or p_command->>'expectedRevision' !~ '^(0|[1-9][0-9]{0,18})$' or length(p_command->>'expectedRevision')=19 and (p_command->>'expectedRevision') collate "C">'9223372036854775807' collate "C" then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  fid:=(p_command->>'figureId')::uuid;
  select * into f from public.historical_figures where id=fid for update;
  if not found then raise exception using errcode='LH005',message='NOT_FOUND'; end if;
  if not f.is_local_hero then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  revision:=f.local_hero_revision::text;
  if f.local_hero_revision<>(p_command->>'expectedRevision')::bigint then raise exception using errcode='40001',message='STALE'; end if;

  if f.workflow_status not in ('draft','needs_revision') then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  if jsonb_typeof(p_command->'storyIds')<>'array' or jsonb_array_length(p_command->'storyIds') not between 1 and 30 or exists(select 1 from jsonb_array_elements(p_command->'storyIds') v where jsonb_typeof(v)<>'string') then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  selected:=array(select jsonb_array_elements_text(p_command->'storyIds')::uuid);
  if cardinality(selected)<>(select count(distinct id) from unnest(selected) id) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  if exists(select 1 from unnest(selected) as chosen(id) where not exists(select 1 from public.figure_stories st where st.id=chosen.id and st.figure_id=fid and st.workflow_status in ('draft','needs_revision'))) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  update public.figure_stories set workflow_status='pending_review',review_note=null,updated_at=now() where figure_id=fid and id=any(selected);
  update public.historical_figures set workflow_status='pending_review',review_note=null where id=fid;

  set constraints all immediate;
  select * into f from public.historical_figures where id=fid;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('figureId',f.id,'slug',f.slug,'revision',f.local_hero_revision::text,'workflow',f.workflow_status,'readiness',readiness));
exception when others then
  code:=case sqlstate when 'LH004' then 'UNAUTHENTICATED' when 'LH002' then 'FORBIDDEN' when 'LH005' then 'NOT_FOUND' when 'LH003' then 'INVALID_TRANSITION' when 'LH001' then 'READINESS_FAILED' when '40001' then 'STALE' when '40P01' then 'STALE' when '23505' then 'CONFLICT' when '23503' then 'CONFLICT' when '22023' then 'INVALID_INPUT' when '22P02' then 'INVALID_INPUT' when '22003' then 'INVALID_INPUT' when '23514' then 'INVALID_INPUT' when '23502' then 'INVALID_INPUT' when '42501' then 'FORBIDDEN' else 'DB_UNAVAILABLE' end;
  message:=case code when 'UNAUTHENTICATED' then 'Vui lòng đăng nhập.' when 'FORBIDDEN' then 'Bạn không có quyền thực hiện thao tác này.' when 'NOT_FOUND' then 'Không tìm thấy hồ sơ.' when 'STALE' then 'Hồ sơ đã thay đổi. Hãy tải lại trước khi lưu.' when 'INVALID_TRANSITION' then 'Trạng thái hiện tại không cho phép thao tác này.' when 'READINESS_FAILED' then 'Hồ sơ chưa đủ điều kiện gửi duyệt hoặc công bố.' when 'CONFLICT' then 'Dữ liệu trùng hoặc còn được tham chiếu.' when 'INVALID_INPUT' then 'Dữ liệu không hợp lệ.' else 'Chưa lưu được hồ sơ. Vui lòng thử lại.' end;
  if code='READINESS_FAILED' and sqlerrm in ('IDENTITY_SOURCE_REQUIRED','CONTRIBUTION_SOURCE_REQUIRED','PERIOD_SOURCE_REQUIRED','PERIOD_OUT_OF_SCOPE','DISPLAYED_CLAIM_SOURCE_REQUIRED','LOCALITY_REQUIRED','LOCALITY_MAPPING_REQUIRED','PRIMARY_STORY_REQUIRED','STORY_SOURCE_REQUIRED','STORY_LENGTH','IMAGE_REQUIRED','IMAGE_IDENTITY','IMAGE_USAGE','SOURCE_METADATA','UNCERTAINTY_NOTE_REQUIRED','INDEPENDENT_SOURCES_REQUIRED','INTERNAL_NOTE','CITATION_MARKER_INVALID') then
    readiness:=jsonb_build_object('blocking',jsonb_build_array(jsonb_build_object('code',sqlerrm,'path','graph','message',message)),'warnings','[]'::jsonb);
  else readiness:=null; end if;
  return jsonb_build_object('ok',false,'error',jsonb_build_object('code',code,'message',message,'fieldErrors','{}'::jsonb,'readiness',readiness,'currentRevision',case when code='STALE' then revision else null end));
end
$command$;
revoke all on function public.local_hero_submit_graph(jsonb) from public, anon;
grant execute on function public.local_hero_submit_graph(jsonb) to authenticated;

create function public.local_hero_review_graph(p_command jsonb) returns jsonb
language plpgsql volatile security invoker set search_path='' as $command$

declare f public.historical_figures; fid uuid; actor public.staff_role; r jsonb; s jsonb; e jsonb; reason text; target public.content_workflow_status; selected uuid[]; code text; message text; revision text; readiness jsonb := '{"blocking":[],"warnings":[]}'::jsonb;
begin
  perform pg_advisory_xact_lock(18012,3401);
  set constraints all deferred;
  if auth.uid() is null then raise exception using errcode='LH004',message='UNAUTHENTICATED'; end if;
  actor:=public.current_staff_role();
  if actor is null then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if actor not in ('reviewer','system_admin') then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if p_command->>'action'='request_revision' then
    if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision','action','reason']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision','action','reason'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if jsonb_typeof(p_command->'reason')<>'string' or length(btrim(p_command->>'reason')) not between 5 and 2000 then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    reason:=p_command->>'reason';
  elsif p_command->>'action'='republish' then
    if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision','action','storyIds']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision','action','storyIds'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    if jsonb_typeof(p_command->'storyIds')<>'array' or jsonb_array_length(p_command->'storyIds') not between 1 and 30 or exists(select 1 from jsonb_array_elements(p_command->'storyIds') v where jsonb_typeof(v)<>'string') then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
    selected:=array(select jsonb_array_elements_text(p_command->'storyIds')::uuid);
    if cardinality(selected)<>(select count(distinct id) from unnest(selected) id) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  elsif p_command->>'action' in ('publish','hide') then
    if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision','action']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision','action'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  else raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if not (p_command ?& array['figureId','expectedRevision']) or jsonb_typeof(p_command->'figureId')<>'string' or jsonb_typeof(p_command->'expectedRevision')<>'string'
    or p_command->>'expectedRevision' !~ '^(0|[1-9][0-9]{0,18})$' or length(p_command->>'expectedRevision')=19 and (p_command->>'expectedRevision') collate "C">'9223372036854775807' collate "C" then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  fid:=(p_command->>'figureId')::uuid;
  select * into f from public.historical_figures where id=fid for update;
  if not found then raise exception using errcode='LH005',message='NOT_FOUND'; end if;
  if not f.is_local_hero then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  revision:=f.local_hero_revision::text;
  if f.local_hero_revision<>(p_command->>'expectedRevision')::bigint then raise exception using errcode='40001',message='STALE'; end if;

  if p_command->>'action' in ('publish','request_revision') and f.workflow_status<>'pending_review' or p_command->>'action'='hide' and f.workflow_status<>'published' or p_command->>'action'='republish' and f.workflow_status<>'hidden' then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  target:=case p_command->>'action' when 'request_revision' then 'needs_revision' when 'hide' then 'hidden' else 'published' end;
  if p_command->>'action'='republish' and exists(select 1 from unnest(selected) as chosen(id) where not exists(select 1 from public.figure_stories st where st.id=chosen.id and st.figure_id=fid and st.workflow_status='hidden')) then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  update public.figure_stories set workflow_status=target,review_note=case when target='needs_revision' then reason when target='hidden' then review_note else null end,updated_at=now() where figure_id=fid and workflow_status=f.workflow_status and (selected is null or id=any(selected));
  update public.historical_figures set workflow_status=target,review_note=case when target='needs_revision' then reason when target='hidden' then review_note else null end where id=fid;

  set constraints all immediate;
  select * into f from public.historical_figures where id=fid;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('figureId',f.id,'slug',f.slug,'revision',f.local_hero_revision::text,'workflow',f.workflow_status,'readiness',readiness));
exception when others then
  code:=case sqlstate when 'LH004' then 'UNAUTHENTICATED' when 'LH002' then 'FORBIDDEN' when 'LH005' then 'NOT_FOUND' when 'LH003' then 'INVALID_TRANSITION' when 'LH001' then 'READINESS_FAILED' when '40001' then 'STALE' when '40P01' then 'STALE' when '23505' then 'CONFLICT' when '23503' then 'CONFLICT' when '22023' then 'INVALID_INPUT' when '22P02' then 'INVALID_INPUT' when '22003' then 'INVALID_INPUT' when '23514' then 'INVALID_INPUT' when '23502' then 'INVALID_INPUT' when '42501' then 'FORBIDDEN' else 'DB_UNAVAILABLE' end;
  message:=case code when 'UNAUTHENTICATED' then 'Vui lòng đăng nhập.' when 'FORBIDDEN' then 'Bạn không có quyền thực hiện thao tác này.' when 'NOT_FOUND' then 'Không tìm thấy hồ sơ.' when 'STALE' then 'Hồ sơ đã thay đổi. Hãy tải lại trước khi lưu.' when 'INVALID_TRANSITION' then 'Trạng thái hiện tại không cho phép thao tác này.' when 'READINESS_FAILED' then 'Hồ sơ chưa đủ điều kiện gửi duyệt hoặc công bố.' when 'CONFLICT' then 'Dữ liệu trùng hoặc còn được tham chiếu.' when 'INVALID_INPUT' then 'Dữ liệu không hợp lệ.' else 'Chưa lưu được hồ sơ. Vui lòng thử lại.' end;
  if code='READINESS_FAILED' and sqlerrm in ('IDENTITY_SOURCE_REQUIRED','CONTRIBUTION_SOURCE_REQUIRED','PERIOD_SOURCE_REQUIRED','PERIOD_OUT_OF_SCOPE','DISPLAYED_CLAIM_SOURCE_REQUIRED','LOCALITY_REQUIRED','LOCALITY_MAPPING_REQUIRED','PRIMARY_STORY_REQUIRED','STORY_SOURCE_REQUIRED','STORY_LENGTH','IMAGE_REQUIRED','IMAGE_IDENTITY','IMAGE_USAGE','SOURCE_METADATA','UNCERTAINTY_NOTE_REQUIRED','INDEPENDENT_SOURCES_REQUIRED','INTERNAL_NOTE','CITATION_MARKER_INVALID') then
    readiness:=jsonb_build_object('blocking',jsonb_build_array(jsonb_build_object('code',sqlerrm,'path','graph','message',message)),'warnings','[]'::jsonb);
  else readiness:=null; end if;
  return jsonb_build_object('ok',false,'error',jsonb_build_object('code',code,'message',message,'fieldErrors','{}'::jsonb,'readiness',readiness,'currentRevision',case when code='STALE' then revision else null end));
end
$command$;
revoke all on function public.local_hero_review_graph(jsonb) from public, anon;
grant execute on function public.local_hero_review_graph(jsonb) to authenticated;

create function public.local_hero_restore_draft(p_command jsonb) returns jsonb
language plpgsql volatile security invoker set search_path='' as $command$

declare f public.historical_figures; fid uuid; actor public.staff_role; r jsonb; s jsonb; e jsonb; reason text; target public.content_workflow_status; selected uuid[]; code text; message text; revision text; readiness jsonb := '{"blocking":[],"warnings":[]}'::jsonb;
begin
  perform pg_advisory_xact_lock(18012,3401);
  set constraints all deferred;
  if auth.uid() is null then raise exception using errcode='LH004',message='UNAUTHENTICATED'; end if;
  actor:=public.current_staff_role();
  if actor is null then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if actor<>'system_admin' then raise exception using errcode='LH002',message='FORBIDDEN'; end if;
  if jsonb_typeof(p_command) is distinct from 'object' or not (p_command ?& array['figureId','expectedRevision']) or exists(select 1 from jsonb_object_keys(p_command) k where k<>all(array['figureId','expectedRevision'])) then raise exception using errcode='22023',message='INVALID_INPUT'; end if;

  if not (p_command ?& array['figureId','expectedRevision']) or jsonb_typeof(p_command->'figureId')<>'string' or jsonb_typeof(p_command->'expectedRevision')<>'string'
    or p_command->>'expectedRevision' !~ '^(0|[1-9][0-9]{0,18})$' or length(p_command->>'expectedRevision')=19 and (p_command->>'expectedRevision') collate "C">'9223372036854775807' collate "C" then raise exception using errcode='22023',message='INVALID_INPUT'; end if;
  fid:=(p_command->>'figureId')::uuid;
  select * into f from public.historical_figures where id=fid for update;
  if not found then raise exception using errcode='LH005',message='NOT_FOUND'; end if;
  if not f.is_local_hero then raise exception using errcode='LH003',message='INVALID_TRANSITION'; end if;
  revision:=f.local_hero_revision::text;
  if f.local_hero_revision<>(p_command->>'expectedRevision')::bigint then raise exception using errcode='40001',message='STALE'; end if;

  update public.figure_stories set workflow_status='draft',review_note=null,updated_at=now() where figure_id=fid and workflow_status<>'draft';
  update public.historical_figures set workflow_status='draft',review_note=null where id=fid;

  set constraints all immediate;
  select * into f from public.historical_figures where id=fid;
  return jsonb_build_object('ok',true,'data',jsonb_build_object('figureId',f.id,'slug',f.slug,'revision',f.local_hero_revision::text,'workflow',f.workflow_status,'readiness',readiness));
exception when others then
  code:=case sqlstate when 'LH004' then 'UNAUTHENTICATED' when 'LH002' then 'FORBIDDEN' when 'LH005' then 'NOT_FOUND' when 'LH003' then 'INVALID_TRANSITION' when 'LH001' then 'READINESS_FAILED' when '40001' then 'STALE' when '40P01' then 'STALE' when '23505' then 'CONFLICT' when '23503' then 'CONFLICT' when '22023' then 'INVALID_INPUT' when '22P02' then 'INVALID_INPUT' when '22003' then 'INVALID_INPUT' when '23514' then 'INVALID_INPUT' when '23502' then 'INVALID_INPUT' when '42501' then 'FORBIDDEN' else 'DB_UNAVAILABLE' end;
  message:=case code when 'UNAUTHENTICATED' then 'Vui lòng đăng nhập.' when 'FORBIDDEN' then 'Bạn không có quyền thực hiện thao tác này.' when 'NOT_FOUND' then 'Không tìm thấy hồ sơ.' when 'STALE' then 'Hồ sơ đã thay đổi. Hãy tải lại trước khi lưu.' when 'INVALID_TRANSITION' then 'Trạng thái hiện tại không cho phép thao tác này.' when 'READINESS_FAILED' then 'Hồ sơ chưa đủ điều kiện gửi duyệt hoặc công bố.' when 'CONFLICT' then 'Dữ liệu trùng hoặc còn được tham chiếu.' when 'INVALID_INPUT' then 'Dữ liệu không hợp lệ.' else 'Chưa lưu được hồ sơ. Vui lòng thử lại.' end;
  if code='READINESS_FAILED' and sqlerrm in ('IDENTITY_SOURCE_REQUIRED','CONTRIBUTION_SOURCE_REQUIRED','PERIOD_SOURCE_REQUIRED','PERIOD_OUT_OF_SCOPE','DISPLAYED_CLAIM_SOURCE_REQUIRED','LOCALITY_REQUIRED','LOCALITY_MAPPING_REQUIRED','PRIMARY_STORY_REQUIRED','STORY_SOURCE_REQUIRED','STORY_LENGTH','IMAGE_REQUIRED','IMAGE_IDENTITY','IMAGE_USAGE','SOURCE_METADATA','UNCERTAINTY_NOTE_REQUIRED','INDEPENDENT_SOURCES_REQUIRED','INTERNAL_NOTE','CITATION_MARKER_INVALID') then
    readiness:=jsonb_build_object('blocking',jsonb_build_array(jsonb_build_object('code',sqlerrm,'path','graph','message',message)),'warnings','[]'::jsonb);
  else readiness:=null; end if;
  return jsonb_build_object('ok',false,'error',jsonb_build_object('code',code,'message',message,'fieldErrors','{}'::jsonb,'readiness',readiness,'currentRevision',case when code='STALE' then revision else null end));
end
