create function public.local_hero_profile(p_slug text) returns jsonb
language sql stable security invoker set search_path='' as $profile$
with person as (
  select * from public.historical_figures where is_local_hero and workflow_status='published' and slug=p_slug and length(p_slug)<=160 and p_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
), citations as (
  select 'figure' owner_kind, fs.figure_id owner_id, fs.claim_key,fs.claim_text,fs.certainty,fs.uncertainty_note,
    jsonb_agg(jsonb_build_object('sourceId',so.id,'title',so.title,'authorOrg',so.author_org,'publisher',so.publisher,'sourceType',so.source_type,'url',so.url,'citation',so.citation,'publishedYear',so.published_year,'accessedAt',so.accessed_at,'locator',fs.locator,'scopeNote',fs.scope_note) order by so.id) sources
  from public.figure_sources fs join person f on f.id=fs.figure_id join public.sources so on so.id=fs.source_id where fs.claim_key not like 'honor:%' or fs.certainty='verified'
  group by fs.figure_id,fs.claim_key,fs.claim_text,fs.certainty,fs.uncertainty_note
  union all
  select 'story',ss.story_id,ss.claim_key,ss.claim_text,ss.certainty,ss.uncertainty_note,
    jsonb_agg(jsonb_build_object('sourceId',so.id,'title',so.title,'authorOrg',so.author_org,'publisher',so.publisher,'sourceType',so.source_type,'url',so.url,'citation',so.citation,'publishedYear',so.published_year,'accessedAt',so.accessed_at,'locator',ss.locator,'scopeNote',ss.scope_note) order by so.id)
  from public.figure_story_sources ss join public.figure_stories st on st.id=ss.story_id join person f on f.id=st.figure_id join public.sources so on so.id=ss.source_id where st.workflow_status='published'
  group by ss.story_id,ss.claim_key,ss.claim_text,ss.certainty,ss.uncertainty_note
), claims as (
  select owner_kind,owner_id,claim_key,certainty,jsonb_build_object('key',claim_key,'text',claim_text,'certainty',certainty,'uncertaintyNote',uncertainty_note,'sources',sources) value from citations
), images as (
  select ma.is_cover,ma.sort_order,ma.id,jsonb_build_object('id',ma.id,'url',ma.file_url,'width',ma.width,'height',ma.height,'altText',ma.alt_text,'caption',ma.caption,'depictionKind',me.depiction_kind,'era',ma.era,
    'labels',to_jsonb(array_remove(array[case when ma.era='historical' then 'Tư liệu lịch sử' else 'Minh họa lịch sử' end,case when me.depiction_kind='historical_context' then 'Tư liệu bối cảnh, không phải chân dung' end,case when ma.is_reenactment then 'Cảnh dựng lại' end,case when ma.is_colorized then 'Ảnh tô màu' end],null)),
    'photographer',ma.photographer,'sourcePageUrl',ma.source_page_url,'license',ma.license,'licenseUrl',ma.license_url,'usageBasis',me.usage_basis,'usageNote',me.usage_note,'focalPoint',ma.focal_point) value
  from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id and me.figure_id=ma.figure_id join person f on f.id=me.figure_id where me.decision='accepted'
), associations as (
  select fl.locality_code,fl.relationship_kind,fl.id,jsonb_build_object('id',fl.id,'locality',jsonb_build_object('code',lo.code,'slug',lo.slug,'officialName',lo.official_name,'referenceFramework',lo.reference_framework),'kind',fl.relationship_kind,'historicalPlaceLabel',fl.historical_place_label,'explanation',fl.explanation,'claim',cl.value,'qualifiesForCoverage',fl.certainty='verified' and fl.relationship_kind in ('birthplace','home_origin','activity')) value
  from public.figure_localities fl join person f on f.id=fl.figure_id join public.history_localities lo on lo.code=fl.locality_code join claims cl on cl.owner_kind='figure' and cl.owner_id=f.id and cl.claim_key=fl.claim_key where fl.certainty in ('verified','approximate','disputed')
), stories as (
  select st.sort_order,st.id,jsonb_build_object('id',st.id,'slug',st.slug,'title',st.title,'summary',st.summary,'body',st.body,'isPrimary',st.is_primary,'sortOrder',st.sort_order,'claims',coalesce((select jsonb_agg(cl.value order by cl.claim_key) from claims cl where cl.owner_kind='story' and cl.owner_id=st.id),'[]'::jsonb)) value
  from public.figure_stories st join person f on f.id=st.figure_id where st.workflow_status='published'
), events as (
  select e.start_year,e.slug,jsonb_build_object('slug',e.slug,'title',e.title,'dateText',e.date_text,'startYear',e.start_year,'relationship',ef.relationship) value
  from public.historical_events e join public.event_figures ef on ef.event_id=e.id join person f on f.id=ef.figure_id where e.workflow_status='published' order by e.start_year,e.slug limit 100
)
select jsonb_build_object('id',f.id,'slug',f.slug,'name',f.name,'aliases',f.catalog_aliases,'birthYear',f.birth_year,'deathYear',f.death_year,
  'birthYearCertainty',(select certainty from claims where owner_kind='figure' and claim_key='birth_year'),
  'deathYearCertainty',(select certainty from claims where owner_kind='figure' and claim_key='death_year'),
  'contributionSummary',f.contribution_summary,'image',(select value from images order by is_cover desc,sort_order nulls last,id limit 1),
  'associations',coalesce((select jsonb_agg(value order by locality_code,relationship_kind,id) from associations),'[]'::jsonb),
  'biography',f.biography,'claims',coalesce((select jsonb_agg(value order by claim_key) from claims where owner_kind='figure'),'[]'::jsonb),
  'stories',coalesce((select jsonb_agg(value order by sort_order,id) from stories),'[]'::jsonb),
  'gallery',coalesce((select jsonb_agg(value order by is_cover desc,sort_order nulls last,id) from images),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(value order by start_year,slug) from events),'[]'::jsonb)) from person f
$profile$;
revoke all on function public.local_hero_profile(text) from public;
grant execute on function public.local_hero_profile(text) to anon,authenticated;

create function public.local_hero_page(p_locality_code text,p_query text,p_page integer) returns jsonb
language sql stable security invoker set search_path='' as $page$
with normalized as (
  select (select code from public.history_localities where code=p_locality_code) code,
    left(normalize(btrim(regexp_replace(regexp_replace(coalesce(p_query,''), U&'[\0009-\000d\0020\0085\00a0\1680\2000-\200a\2028\2029\202f\205f\3000]+',' ','g'),U&'[\0001-\0008\000e-\001f\007f-\009f\200b\feff]','','g')),NFC),120) query,
    case when p_page between 1 and 999999 then p_page else 1 end requested_page
), matches as (
  select f.id,f.slug,f.name from public.historical_figures f cross join normalized n
  where f.is_local_hero and f.workflow_status='published'
    and (n.code is null or exists(select 1 from public.figure_localities fl where fl.figure_id=f.id and fl.locality_code=n.code and fl.certainty='verified' and fl.relationship_kind in ('birthplace','home_origin','activity')))
    and not exists(select 1 from unnest(string_to_array(public.local_hero_fold(n.query),' ')) token where token<>'' and strpos(f.local_hero_search_text,token)=0)
), totals as (
  select count(*)::integer total,ceil(count(*)/12.0)::integer pages from matches
), bounds as (
  select n.*,t.*,least(n.requested_page,greatest(1,t.pages)) page from normalized n cross join totals t
), selected as (
  select m.* from matches m order by m.name collate public.local_heroes_vi,m.slug collate "C" limit 12 offset (select (page-1)*12 from bounds)
), page_people as materialized (
  select f.* from public.historical_figures f join selected s on s.id=f.id
), page_claims as materialized (
  select fs.figure_id,fs.claim_key,fs.certainty,jsonb_build_object('key',fs.claim_key,'text',fs.claim_text,'certainty',fs.certainty,'uncertaintyNote',fs.uncertainty_note,
    'sources',jsonb_agg(jsonb_build_object('sourceId',so.id,'title',so.title,'authorOrg',so.author_org,'publisher',so.publisher,'sourceType',so.source_type,'url',so.url,'citation',so.citation,'publishedYear',so.published_year,'accessedAt',so.accessed_at,'locator',fs.locator,'scopeNote',fs.scope_note) order by so.id)) value
  from public.figure_sources fs join page_people f on f.id=fs.figure_id join public.sources so on so.id=fs.source_id
  group by fs.figure_id,fs.claim_key,fs.claim_text,fs.certainty,fs.uncertainty_note
), page_images as materialized (
  select me.figure_id,ma.is_cover,ma.sort_order,ma.id,jsonb_build_object('id',ma.id,'url',ma.file_url,'width',ma.width,'height',ma.height,'altText',ma.alt_text,'caption',ma.caption,'depictionKind',me.depiction_kind,'era',ma.era,
    'labels',to_jsonb(array_remove(array[case when ma.era='historical' then 'Tư liệu lịch sử' else 'Minh họa lịch sử' end,case when me.depiction_kind='historical_context' then 'Tư liệu bối cảnh, không phải chân dung' end,case when ma.is_reenactment then 'Cảnh dựng lại' end,case when ma.is_colorized then 'Ảnh tô màu' end],null)),
    'photographer',ma.photographer,'sourcePageUrl',ma.source_page_url,'license',ma.license,'licenseUrl',ma.license_url,'usageBasis',me.usage_basis,'usageNote',me.usage_note,'focalPoint',ma.focal_point) value
  from public.media_assets ma join public.figure_media_evidence me on me.media_id=ma.id and me.figure_id=ma.figure_id join page_people f on f.id=me.figure_id where me.decision='accepted'
), page_associations as materialized (
  select fl.figure_id,fl.locality_code,fl.relationship_kind,fl.id,jsonb_build_object('id',fl.id,'locality',jsonb_build_object('code',lo.code,'slug',lo.slug,'officialName',lo.official_name,'referenceFramework',lo.reference_framework),'kind',fl.relationship_kind,'historicalPlaceLabel',fl.historical_place_label,'explanation',fl.explanation,'claim',cl.value,'qualifiesForCoverage',fl.certainty='verified' and fl.relationship_kind in ('birthplace','home_origin','activity')) value
  from public.figure_localities fl join page_people f on f.id=fl.figure_id join public.history_localities lo on lo.code=fl.locality_code join page_claims cl on cl.figure_id=f.id and cl.claim_key=fl.claim_key where fl.certainty in ('verified','approximate','disputed')
), page_items as (
  select f.name,f.slug,jsonb_build_object('id',f.id,'slug',f.slug,'name',f.name,'aliases',f.catalog_aliases,'birthYear',f.birth_year,'deathYear',f.death_year,
    'birthYearCertainty',(select certainty from page_claims cl where cl.figure_id=f.id and cl.claim_key='birth_year'),
    'deathYearCertainty',(select certainty from page_claims cl where cl.figure_id=f.id and cl.claim_key='death_year'),
    'contributionSummary',f.contribution_summary,'image',(select value from page_images im where im.figure_id=f.id order by is_cover desc,sort_order nulls last,id limit 1),
    'associations',coalesce((select jsonb_agg(value order by locality_code,relationship_kind,id) from page_associations a where a.figure_id=f.id),'[]'::jsonb)) value from page_people f
), locality_counts as (
  select lo.code,count(distinct f.id)::integer eligible_people from public.history_localities lo
  left join public.figure_localities fl on fl.locality_code=lo.code and fl.certainty='verified' and fl.relationship_kind in ('birthplace','home_origin','activity')
  left join public.historical_figures f on f.id=fl.figure_id and f.is_local_hero and f.workflow_status='published' group by lo.code
)
select jsonb_build_object('filters',jsonb_build_object('localityCode',b.code,'query',b.query,'page',b.page),'pageSize',12,'totalPeople',b.total,'totalPages',b.pages,
  'items',coalesce((select jsonb_agg(s.value order by s.name collate public.local_heroes_vi,s.slug collate "C") from page_items s),'[]'::jsonb),
  'coverage',jsonb_build_object('framework','VN-34-2025','totalLocalities',34,'representedLocalities',(select count(*) from locality_counts where eligible_people>0),'byLocality',(select jsonb_agg(jsonb_build_object('code',code,'eligiblePeople',eligible_people) order by code) from locality_counts))) from bounds b
$page$;
revoke all on function public.local_hero_page(text,text,integer) from public;
grant execute on function public.local_hero_page(text,text,integer) to anon,authenticated;
